-- 49 Stage Night: runs the lighting desk. The beams are the engine's
-- `freeform_light`s: this turns them (they swing with their entity), and sets
-- their colour and brightness with Lighting.set_color / set_intensity, on the
-- band's beat. Generated by tools/gen_scenes.py.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/49-stage-night.scene"
local COUNT = 6
local BEAT = 60 / 112.0
local captions = true
local beams, glows = {}, {}
local wash, status
local t, cue, strobe = 0, 1, 0
local NAMES = { "warm", "cool", "rainbow", "chase" }

local function hue(h)
    h = h % 1
    local r = math.abs(h * 6 - 3) - 1
    local g = 2 - math.abs(h * 6 - 2)
    local b = 2 - math.abs(h * 6 - 4)
    return math.max(0, math.min(1, r)), math.max(0, math.min(1, g)), math.max(0, math.min(1, b))
end

function init(entity)
    for i = 1, COUNT do
        beams[i] = Entity.find_by_name("Beam" .. i)
        glows[i] = Entity.find_by_name("LampGlow" .. i)
    end
    wash = Entity.find_by_name("Wash")
    status = Entity.find_by_name("Status")
end

function update(entity, dt)
    nav.tick(SCENE)
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end
    for i = 1, 4 do
        if Input.is_key_just_pressed(tostring(i)) then cue = i end
    end
    if Input.is_key_just_pressed("Space") then strobe = 0.6 end
    t = t + dt
    local beat = t / BEAT
    local phase = beat % 1
    local kick = math.exp(-phase * 5)

    for i = 1, COUNT do
        local b = beams[i]
        if b then
            local side = (i % 2 == 0) and 1 or -1
            local angle, r, g, bl, k
            if cue == 1 then
                angle = 0.24 * math.sin(t * 0.7 + i * 0.3) * side
                r, g, bl = 1.0, 0.55 + 0.15 * (i % 2), 0.2
                k = 1.0 + 0.5 * kick
            elseif cue == 2 then
                angle = 0.28 * math.sin(t * 0.45 + i * 0.4) * side
                r, g, bl = 0.25, 0.55 + 0.2 * (i % 2), 1.0
                k = 1.1 + 0.3 * kick
            elseif cue == 3 then
                angle = 0.35 * math.sin(beat * math.pi / 4 + i * 0.9)
                r, g, bl = hue(t * 0.12 + i / COUNT)
                k = 1.1 + 0.6 * kick
            else
                -- A chase: one beam after another, on the beat.
                local lit = (math.floor(beat) % COUNT) + 1
                angle = 0.25 * math.sin(beat * math.pi / 2) * side
                r, g, bl = 1.0, 0.25, 0.65
                k = (i == lit) and (1.8 * (0.4 + 0.6 * kick)) or 0.12
            end
            Transform.set_rotation(b, angle)
            Lighting.set_color(b, r, g, bl)
            Lighting.set_intensity(b, k)
            if glows[i] then Sprite.set_color(glows[i], r * 2 * k, g * 2 * k, bl * 2 * k, 1) end
        end
    end

    -- The strobe: a few white flashes over the whole stage.
    if strobe > 0 then
        strobe = strobe - dt
        local on = (math.floor(strobe * 20) % 2) == 0
        Lighting.set_intensity(wash, on and 1.6 or 0)
    else
        Lighting.set_intensity(wash, 0)
    end
    if status then UI.set_text(status, "cue: " .. NAMES[cue]) end
end
